<?php
/** TPL-03 category mode: published content and term metadata only. */
if (!defined('ABSPATH')) exit;
$term = get_queried_object();
if (!($term instanceof WP_Term)) { get_header(); get_footer(); return; }
$title = interworld_term_field('iw_tpl03_title', $term) ?: $term->name;
$subtitle = interworld_term_field('iw_tpl03_subtitle', $term);
$description = interworld_term_field('iw_tpl03_hero_description', $term) ?: term_description($term->term_id, 'object_type');
$image = interworld_term_image_url($term);
$intro = interworld_term_field('iw_tpl03_intro', $term);
$groups = interworld_child_groups($term);
$faq = interworld_tpl03_faq($term);
$sources = interworld_tpl03_links($term, 'source');
$books = interworld_tpl03_links($term, 'book');
$page = max(1, (int) get_query_var('paged'));
$objects = new WP_Query(array('post_type' => 'interworld_object', 'post_status' => 'publish',
    'posts_per_page' => 12, 'paged' => $page, 'orderby' => 'title', 'order' => 'ASC',
    'tax_query' => array(array('taxonomy' => 'object_type', 'field' => 'term_id', 'terms' => $term->term_id))));
$count = (int) $objects->found_posts;
get_header(); ?>
<main class="interworld-category-page">
<section class="category-hero" id="definition">
<?php if ($image) : ?><img class="category-hero-image" src="<?php echo esc_url($image); ?>" alt="" loading="eager"><?php endif; ?>
<div class="category-hero-content"><div class="category-breadcrumbs"><a href="<?php echo esc_url(home_url('/')); ?>">География Межмирья</a> · <span><?php echo esc_html($term->name); ?></span></div><div class="category-eyebrow">ЭНЦИКЛОПЕДИЯ МЕЖМИРЬЯ</div><h1><?php echo esc_html($title); ?></h1>
<?php if ($subtitle) : ?><div class="category-subtitle"><?php echo esc_html($subtitle); ?></div><?php endif; ?>
<?php if ($description) : ?><div class="category-hero-description"><?php echo wp_kses_post($description); ?></div><?php endif; ?>
<div class="category-stats"><div class="category-stat"><strong><?php echo esc_html($count); ?></strong><span>опубликовано</span></div><div class="category-stat"><strong><?php echo esc_html(count($groups)); ?></strong><span>группы</span></div></div></div></section>
<nav class="category-anchor-nav" aria-label="Навигация по странице"><div class="category-inner" style="display:flex;min-width:max-content;padding-top:0;padding-bottom:0"><a href="#definition">Определение</a><?php if ($intro) : ?><a href="#about-category">О категории</a><?php endif; ?><?php if ($groups) : ?><a href="#system">Группы</a><?php endif; ?><?php if ($count) : ?><a href="#catalog">Каталог</a><?php endif; ?><?php if ($faq) : ?><a href="#faq">Вопросы и ответы</a><?php endif; ?><?php if ($sources) : ?><a href="#sources">Источники</a><?php endif; ?><?php if ($books) : ?><a href="#books">Книги</a><?php endif; ?></div></nav>
<?php if ($intro) : ?><section class="category-section" id="about-category"><div class="category-inner"><div class="category-intro-grid"><div><div class="section-eyebrow">О КАТЕГОРИИ</div><h2 class="category-intro-title"><?php echo esc_html(interworld_term_field('iw_tpl03_intro_title', $term) ?: 'О категории'); ?></h2></div><div class="category-intro-copy"><?php echo wp_kses_post($intro); ?></div></div></div></section><?php endif; ?>
<?php if ($groups) : ?><section class="category-section system-section" id="system"><div class="category-inner"><div class="section-heading"><div class="section-eyebrow">СТРУКТУРА КАТЕГОРИИ</div><h2><?php echo esc_html(interworld_term_field('iw_tpl03_system_title', $term) ?: 'Группы'); ?></h2><?php if (interworld_term_field('iw_tpl03_system_intro', $term)) : ?><p class="category-section-intro"><?php echo esc_html(interworld_term_field('iw_tpl03_system_intro', $term)); ?></p><?php endif; ?></div><div class="system-grid"><?php foreach ($groups as $group) : $link = get_term_link($group); if (is_wp_error($link)) continue; ?><a class="system-card" href="<?php echo esc_url($link); ?>"><div class="system-orb"><strong><?php echo esc_html((int) $group->count); ?></strong></div><h3><?php echo esc_html($group->name); ?></h3><?php if ($group->description) : ?><p><?php echo esc_html(wp_strip_all_tags($group->description)); ?></p><?php endif; ?></a><?php endforeach; ?></div></div></section><?php endif; ?>
<?php if ($count) : ?><section class="category-section catalog-section" id="catalog"><div class="category-inner"><div class="section-heading"><div class="section-eyebrow">КАТАЛОГ</div><h2><?php echo esc_html($term->name); ?></h2></div><div class="category-card-grid"><?php foreach ($objects->posts as $object) : $id = $object->ID; $code = function_exists('get_field') ? get_field('object_code', $id) : ''; $number = function_exists('get_field') ? get_field('object_number', $id) : ''; $thumb = get_the_post_thumbnail_url($id, 'large'); $excerpt = get_the_excerpt($id); ?><article class="category-card"><div class="category-card-image"><?php if ($thumb) : ?><img src="<?php echo esc_url($thumb); ?>" alt="" loading="lazy"><?php endif; ?></div><div class="category-card-body"><?php if ($number !== '' && $number !== null) : ?><div class="category-card-number"><?php echo esc_html($number); ?></div><?php endif; ?><?php if ($code) : ?><div class="category-card-code"><?php echo esc_html($code); ?></div><?php endif; ?><div class="category-card-title"><?php echo esc_html(get_the_title($id)); ?></div><?php if ($excerpt) : ?><p class="category-card-description"><?php echo esc_html($excerpt); ?></p><?php endif; ?><a class="category-card-link" href="<?php echo esc_url(get_permalink($id)); ?>" aria-label="Открыть <?php echo esc_attr(get_the_title($id)); ?>">›</a></div></article><?php endforeach; ?></div><?php if ($objects->max_num_pages > 1) : ?><div class="pagination" aria-label="Пагинация"><?php echo wp_kses_post(paginate_links(array('current' => $page, 'total' => $objects->max_num_pages, 'type' => 'list', 'prev_text' => '←', 'next_text' => '→'))); ?></div><?php endif; ?></div></section><?php endif; ?>
<?php if ($faq) : ?><section class="category-section faq-section" id="faq"><div class="category-inner"><div class="faq-layout"><div><div class="section-eyebrow">ЧАСТЫЕ ВОПРОСЫ</div><h2>Вопросы и ответы</h2></div><div class="faq-list"><?php foreach ($faq as $item) : ?><details class="faq-item"><summary><?php echo esc_html($item['q']); ?></summary><div class="faq-answer"><?php echo wp_kses_post(wpautop($item['a'])); ?></div></details><?php endforeach; ?></div></div></div></section><?php endif; ?>
<?php foreach (array('sources' => $sources, 'books' => $books) as $section => $items) : if (!$items) continue; ?><section class="category-section" id="<?php echo esc_attr($section); ?>"><div class="category-inner"><div class="section-heading"><div class="section-eyebrow">МАТЕРИАЛЫ</div><h2><?php echo $section === 'books' ? 'Книги' : 'Источники'; ?></h2></div><div class="<?php echo $section === 'books' ? 'books-grid' : 'source-grid'; ?>"><?php foreach ($items as $item) : ?><a class="<?php echo $section === 'books' ? 'book-card' : 'source-card'; ?>" href="<?php echo esc_url($item['url']); ?>"><div><div class="<?php echo $section === 'books' ? 'book-title' : 'source-title'; ?>"><?php echo esc_html($item['title']); ?></div><?php if ($item['description']) : ?><p><?php echo esc_html($item['description']); ?></p><?php endif; ?></div></a><?php endforeach; ?></div></div></section><?php endforeach; ?>
</main>
<?php wp_reset_postdata(); get_footer(); ?>
